def add(a,b):return [x+y for x,y in zip(a,b)]
def sub(a,b):return [x-y for x,y in zip(a,b)]
def mul(a,t):return [x*t for x in a]
def lerp(a,b,t):return add(a,mul(sub(b,a),t))
def cross(a,b):return [a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]]
def dot(a,b):return sum(x*y for x,y in zip(a,b))
def norm(a):return math.sqrt(dot(a,a))
def V(label,segs=None,poly=None,pts=None):
 d={'label':label}
 if segs:d['segments']=segs
 if poly:d['polygon']=poly
 if pts:d['points']=pts
 return d

def G(p,e=None,f=None,v=None,names=None,planar=False):
 d={'points':p,'edges':e or [],'views':{'neutral':V('Условие задачи'),**(v or {})},'labelNames':list(p) if names is None else names}
 if f:d['faces']=f
 if planar:d['planar']=True
 labels={k:k[0]+'₁' for k in p if len(k)==2 and k.endswith('1') and k[0].isupper()}
 if labels:d['labels']=labels
 return d

def cube(x=4,y=4,z=4):
 p={'A':[0,0,0],'B':[0,y,0],'C':[x,y,0],'D':[x,0,0],'A1':[0,0,z],'B1':[0,y,z],'C1':[x,y,z],'D1':[x,0,z]}
 e=[['A','B'],['B','C'],['C','D'],['D','A'],['A1','B1'],['B1','C1'],['C1','D1'],['D1','A1'],['A','A1'],['B','B1'],['C','C1'],['D','D1']]
 f=[['A','D','C','B'],['A1','B1','C1','D1'],['A','B','B1','A1'],['B','C','C1','B1'],['C','D','D1','C1'],['D','A','A1','D1']]
 return p,e,f

def tetra(regular=None):
 if regular:
  a=regular;p={'A':[0,0,0],'B':[a,0,0],'C':[a/2,a*math.sqrt(3)/2,0],'D':[a/2,a*math.sqrt(3)/6,a*math.sqrt(2/3)]}
 else:p={'A':[-2,-1,0],'B':[2,-1,0],'C':[1,3,0],'D':[0,0,4]}
 e=[['A','B'],['A','C'],['B','C'],['D','A'],['D','B'],['D','C']];f=[['A','C','B'],['A','B','D'],['B','C','D'],['C','A','D']]
 return p,e,f

def plane(p,z=0,size=4,prefix='p'):
 keys=[prefix+str(i) for i in range(4)];p.update(dict(zip(keys,[[-size,-size,z],[size,-size,z],[size,size,z],[-size,size,z]])));return keys

def S(title,text,why,view='neutral',prompt=None):return {'title':title,'prompt':prompt or title+'. Объясни свой выбор.','explanation':text,'justifications':[{'kind':'theorem','text':why}],'view':view}

def card(sec,n,title,text,goal,g,steps,hint,parts=None,subpart=None,pages=None,caption=CAP):
 number=f'{sec}.{n}';source0=SOURCES[number];src={k:copy.deepcopy(source0['source'][k]) for k in ['bookId','collection','exercise','chapter','printedPages','pdfPages']}
 if pages:src['printedPages']=pages;src['pdfPages']=[p+1 for p in pages]
 suffix='-'+subpart if subpart else '';identifier=f'merz-ex-{sec:02}-{n:03}'+suffix;file=f'ex-{sec:02}-{n:03}'+suffix+'.json'
 if subpart:src['subpart']=subpart
 for i,s in enumerate(steps,1):s['id']=f'step-{i}'
 d={'schemaVersion':1,'revision':1,'id':identifier,'kind':'exercise','title':number+('('+subpart+')' if subpart else '')+'. '+title,'status':'draft','source':src,'statement':{'text':text,'goal':goal},'visualization':{'type':'scene3d','caption':caption,'model':g},'help':[{'id':'help-1','question':hint[0],'text':hint[1]}],'steps':steps,'answer':{'mode':'manual','prompt':'Запиши ответ, ход построения или доказательство. Рассуждение сохраняется для обсуждения с преподавателем и автоматически не оценивается.'},'review':{'source':'pending','mathematics':'pending','pedagogy':'pending'}}
 (OUT/file).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
 c=next((c for c in coverage if c['exercise']==number),None)
 if not c:
  c={'sourceEntryId':source0['id'],'exercise':number,'requiredParts':[],'textbookParts':parts or [],'sourcePdfPages':[],'lessonFiles':[]};coverage.append(c)
 c['requiredParts'].append(subpart);c['sourcePdfPages']=sorted(set(c['sourcePdfPages']+src['pdfPages']));c['lessonFiles'].append('stereo-course/merzlyak-10-base/lessons/'+file)

PERP='Если плоскость содержит прямую, перпендикулярную другой плоскости, то эти плоскости перпендикулярны.'
LINEP='Прямая, перпендикулярная двум пересекающимся прямым плоскости, перпендикулярна этой плоскости.'
PP='В двух перпендикулярных плоскостях прямая одной плоскости, перпендикулярная их общей прямой, перпендикулярна другой плоскости.'
PYTH='Теорема Пифагора.'
ANGLE='Угол между прямой и плоскостью — угол между прямой и её ортогональной проекцией.'
def edges(*cycles):
 out=[]
 for cyc in cycles:
  for a,b in zip(cyc,cyc[1:]+cyc[:1]):
   if [a,b] not in out and [b,a] not in out:out.append([a,b])
 return out
p,e,f=cube(5,4,3)
card(14,1,'Перпендикулярные плоскости вокруг нас','Приведите примеры перпендикулярных плоскостей, используя окружающие предметы.','Объяснить прямой двугранный угол.',G(p,e,f,{'pair':V('Пол и вертикальная стена',poly=['A','B','B1','A1'])},names=['A','B','A1']),[S('Выбери две поверхности','Плоскость горизонтального пола и плоскость вертикальной стены дают пример перпендикулярных плоскостей.','Геометрическая модель поверхностей комнаты.','pair'),S('Покажи линейный угол','По полу и стене через одну точку их стыка проведём прямые, перпендикулярные стыку. Они образуют угол 90°.','Определение линейного угла двугранного угла.'),S('Приведи ещё пример','Такие же отношения имеют горизонтальная столешница и вертикальная боковая стенка прямоугольного шкафа, если их плоскости рассматриваются с продолжениями.','Плоскости перпендикулярны, если угол между ними равен 90°.')],('Достаточно ли назвать любые две стены?','Нужно знать, что угол между их плоскостями прямой. Это не обязательно верно для любого помещения.'))
p,e,f=cube();p['O']=[2,2,0];e += [['A','C'],['B','D']]
card(14,2,'Четыре пары плоскостей куба','В кубе ABCDA₁B₁C₁D₁ перпендикулярны ли: 1) A₁B₁C₁ и CDD₁; 2) ABC и A₁B₁C₁; 3) AA₁C₁ и ABC; 4) ACC₁ и BDD₁?','Для каждой пары назвать основание ответа.',G(p,e,f,{'one':V('Соседние грани',poly=['C','D','D1','C1']),'three':V('Диагональная вертикальная плоскость',poly=['A','A1','C1','C']),'four':V('Перпендикулярные диагонали',[['A','C'],['B','D']],pts=['O'])}),[S('Пара 1','Да: плоскость CDD₁ содержит CC₁, перпендикулярную плоскости верхней грани A₁B₁C₁.',PERP,'one'),S('Пара 2','Нет: плоскости нижней и верхней граней куба параллельны, угол между ними равен 0°.','Свойства куба.'),S('Пара 3','Да: плоскость AA₁C₁ содержит AA₁⊥(ABC).',PERP,'three'),S('Пара 4','Да. AC⊥BD как диагонали квадрата и AC⊥DD₁ как горизонтальная прямая вертикальному ребру. Значит AC⊥(BDD₁); плоскость ACC₁ содержит AC и перпендикулярна BDD₁.',LINEP+' '+PERP,'four')],('Достаточно ли общей прямой двух плоскостей?','Нет: нужно показать угол 90° или найти в одной плоскости прямую, перпендикулярную другой.'),parts=list('1234'))
p,e,f=cube()
card(14,3,'Три утверждения о перпендикулярных плоскостях','Верно ли: 1) при α⊥β любая прямая α перпендикулярна β; 2) при α⊥β плоскость α перпендикулярна любой прямой, параллельной β; 3) две плоскости, перпендикулярные третьей, параллельны?','Опровергнуть каждое утверждение конкретным примером.',G(p,e,f,{'one':V('Общая прямая AB',[['A','B']],['A','B','B1','A1']),'two':V('C₁D₁ параллельна обеим плоскостям',[['C1','D1']]),'three':V('Две соседние вертикальные грани',poly=['A','D','D1','A1'])}),[S('Утверждение 1','Неверно: для α=(ABB₁), β=(ABCD) общая прямая AB лежит в обеих плоскостях и не перпендикулярна β.','Контрпример.','one'),S('Утверждение 2','Неверно: при тех же α,β прямая C₁D₁ параллельна β и α. Поэтому α не перпендикулярна ей.','Контрпример.','two'),S('Утверждение 3','Неверно: соседние боковые грани ABB₁A₁ и ADD₁A₁ обе перпендикулярны основанию, но пересекаются по AA₁.','Контрпример.','three')],('Какую прямую удобно взять для первого контрпримера?','Линию пересечения самих перпендикулярных плоскостей.'),parts=list('123'))
