card(15,15,'Сечение куба при разных углах наклона','Ребро куба равно a. Найдите площадь сечения плоскостью через AD, образующей угол α с плоскостью ABC.','Учесть смену граней, на которых заканчивается сечение.',G(p,e,f,{'low':V('Пример α=30°: сечение до дальней грани',poly=['A','D','Q','P']),'high':V('Пример α=60°: сечение до верхней грани',poly=['A','D','U','T'])}),[S('Рассмотри боковую грань','Плоскость через AD пересекает грань ABB₁A₁ по прямой через A под углом α к AB. Сечение — прямоугольник со стороной AD=a; другая сторона заканчивается на BB₁ либо A₁B₁. Рассматриваем плоскость, входящую внутрь куба.','AD перпендикулярна боковой грани.'),S('Случай 0°≤α≤45°','Прямая из A встречает BB₁; проекция всего сечения на основание — квадрат площадью a². Поэтому S cosα=a² и S=a²/cosα.',PROJ,'low'),S('Случай 45°≤α≤90°','Прямая из A встречает A₁B₁. Её вертикальная проекция имеет длину a, значит длина стороны сечения a/sinα. Поэтому S=a²/sinα. Эквивалентно можно проектировать сечение на вертикальную грань.','Синус острого угла прямоугольного треугольника.','high'),S('Проверь границу','При α=45° обе формулы дают a²√2. При α=0° или 90° сечение совпадает с гранью и имеет площадь a². Ответ задаётся двумя указанными формулами.','cos45°=sin45°; предельные положения плоскости.')],('Почему одной формулы a²/cosα недостаточно?','После 45° сечение достигает верхней грани раньше дальней, и его проекция перестаёт покрывать всё основание.'),caption=CAP+' На одной модели показаны два разных сечения: для 30° и 60°. Каждый шаг выделяет свой случай.')
