card(15,19,'Площадь по стороне и двум углам','В ABC известны AC=b, ∠A=α, ∠B=β. Найдите площадь треугольника.','Выразить вторую сторону по теореме синусов.',G(p,edges(['A','B','C']),v={'triangle':V('Сторона b и углы α,β',poly=['A','B','C'])},planar=True),[S('Найди третий угол','∠C=180°−α−β. Для существования невырожденного треугольника b>0, α>0, β>0 и α+β<180°.','Сумма углов треугольника.','triangle'),S('Вырази AB','По теореме синусов AB/sinC=b/sinβ. Так как sinC=sin(α+β), получаем AB=b sin(α+β)/sinβ.','Теорема синусов.'),S('Найди площадь','S=(1/2)AC·AB·sinα=b² sinα·sin(α+β)/(2 sinβ). Ответ: b² sinα sin(α+β)/(2 sinβ).','Площадь треугольника по двум сторонам и углу между ними.','triangle')],('Какую сторону удобно найти второй?','AB: она образует с данной AC известный угол α.'))
